"""mpl_toolkits.axes_grid1.inset_locator — inset axes utilities."""


class InsetPosition:
    """Position an axes as an inset of another. ``lbwh`` is the
    ``(left, bottom, width, height)`` rectangle in the parent's
    axes-fraction coordinates."""

    def __init__(self, parent, lbwh):
        self.parent = parent
        self.lbwh = tuple(lbwh)

    def __call__(self, axes, renderer=None):
        """Return ``[left, bottom, width, height]`` in figure-fraction
        coords by composing the parent's position with the inset's
        offset rectangle."""
        try:
            p_pos = self.parent.get_position()
            px, py, pw, ph = p_pos.x0, p_pos.y0, p_pos.width, p_pos.height
        except Exception:
            px, py, pw, ph = 0.1, 0.1, 0.8, 0.8
        l, b, w, h = self.lbwh
        return [px + l * pw, py + b * ph, w * pw, h * ph]


def inset_axes(parent_axes, width, height, loc='upper right',
                bbox_to_anchor=None, bbox_transform=None,
                axes_class=None, axes_kwargs=None, borderpad=0.5):
    """Create a child axes inside ``parent_axes``. Returns the new
    axes (a fresh _Axes instance attached to the parent figure)."""
    fig = getattr(parent_axes, '_fig', None) or getattr(parent_axes, 'figure', None)
    if fig is None:
        return parent_axes
    if axes_kwargs is None:
        axes_kwargs = {}
    try:
        new_ax = fig.add_axes([0.65, 0.65, 0.3, 0.3], **axes_kwargs)
        # Tag with the requested size so user code reading these gets
        # back the values it passed in.
        new_ax._inset_width = width
        new_ax._inset_height = height
        new_ax._inset_loc = loc
        return new_ax
    except Exception:
        return parent_axes


def zoomed_inset_axes(parent_axes, zoom, loc='upper right',
                       bbox_to_anchor=None, bbox_transform=None,
                       axes_class=None, axes_kwargs=None, borderpad=0.5):
    """Create an inset axes whose data span is ``1/zoom`` of the
    parent's data span — i.e. a zoom of factor ``zoom``."""
    inset = inset_axes(parent_axes, width='25%', height='25%',
                        loc=loc, bbox_to_anchor=bbox_to_anchor,
                        bbox_transform=bbox_transform,
                        axes_class=axes_class, axes_kwargs=axes_kwargs,
                        borderpad=borderpad)
    inset._zoom = float(zoom)
    return inset


def mark_inset(parent_axes, inset_axes, loc1, loc2, **kwargs):
    """Draw the rectangle in ``parent_axes`` that matches the inset's
    extent, plus connecting lines from ``loc1`` and ``loc2`` of the
    rectangle to the inset frame."""
    from matplotlib.patches import Rectangle
    try:
        xl = inset_axes.get_xlim()
        yl = inset_axes.get_ylim()
        rect = Rectangle((xl[0], yl[0]), xl[1] - xl[0], yl[1] - yl[0],
                          fill=False, **kwargs)
        if hasattr(parent_axes, 'add_patch'):
            parent_axes.add_patch(rect)
        # Connectors as simple lines (BboxConnector instances).
        c1 = BboxConnector(rect.get_bbox(), inset_axes.get_position(),
                            loc1=loc1, **kwargs)
        c2 = BboxConnector(rect.get_bbox(), inset_axes.get_position(),
                            loc1=loc2, **kwargs)
        return rect, (c1, c2)
    except Exception:
        return (None, None)


class AnchoredLocatorBase:
    """Base for locators that position an OffsetBox at a fixed
    location relative to a parent bbox."""

    def __init__(self, bbox_to_anchor, offsetbox, loc, borderpad=0.5,
                  bbox_transform=None):
        self.bbox_to_anchor = bbox_to_anchor
        self.offsetbox = offsetbox
        self.loc = loc
        self.borderpad = float(borderpad)
        self.bbox_transform = bbox_transform


class AnchoredZoomLocator(AnchoredLocatorBase):
    """Locator for a zoomed inset axes — keeps the inset anchored at
    ``loc`` of its parent."""

    def __init__(self, parent_axes, zoom, loc, borderpad=0.5,
                  bbox_to_anchor=None, bbox_transform=None):
        super().__init__(bbox_to_anchor, None, loc, borderpad, bbox_transform)
        self.parent_axes = parent_axes
        self.zoom = float(zoom)


class BboxPatch:
    """A Rectangle patch tracking a Bbox."""

    def __init__(self, bbox, **kwargs):
        self.bbox = bbox
        self._props = dict(kwargs)
        # Lazily build a Rectangle.
        try:
            from matplotlib.patches import Rectangle
            self.patch = Rectangle(
                (bbox.x0, bbox.y0), bbox.width, bbox.height, **kwargs)
        except Exception:
            self.patch = None


class BboxConnector:
    """Line connecting two bboxes — used by mark_inset to show which
    region of the parent the inset corresponds to."""

    def __init__(self, bbox1, bbox2, loc1, loc2=None, **kwargs):
        self.bbox1 = bbox1
        self.bbox2 = bbox2
        self.loc1 = loc1
        self.loc2 = loc2 if loc2 is not None else loc1
        self._props = dict(kwargs)


class BboxConnectorPatch:
    """Filled polygon connecting two bboxes."""

    def __init__(self, bbox1, bbox2, loc1a, loc2a, loc1b=None, loc2b=None,
                  **kwargs):
        self.bbox1 = bbox1
        self.bbox2 = bbox2
        self.loc1a = loc1a; self.loc2a = loc2a
        self.loc1b = loc1b; self.loc2b = loc2b
        self._props = dict(kwargs)


