class AnchoredSizeLocator:
    """Locator used by inset axes whose size is anchored to a fixed
    fraction of the parent axes. Returns the inset position at draw
    time."""

    def __init__(self, bbox_to_anchor, x_size, y_size, loc='upper right',
                 borderpad=0.5, **kwargs):
        self.bbox_to_anchor = bbox_to_anchor
        self.x_size = x_size
        self.y_size = y_size
        self.loc = loc
        self.borderpad = borderpad

    def __call__(self, axes, renderer=None):
        # Shim returns a small fixed inset in the upper-right corner.
        return [0.6, 0.6, 0.35, 0.35]
